 21	const defaultExampleDir = "testdata/jsverbs"
 22	
 23	func main() {
 24		dir := discoverDirectory(os.Args[1:])
 25	
 26		registry, err := jsverbs.ScanDir(dir)
 27		if err != nil {
 28			fmt.Fprintln(os.Stderr, err)
 29			os.Exit(1)
 30		}
 31		if err := registerExampleSharedSections(dir, registry); err != nil {
 32			fmt.Fprintln(os.Stderr, err)
 33			os.Exit(1)
 34		}
 35	
 36		commands, err := registry.Commands()
 37		if err != nil {
 38			fmt.Fprintln(os.Stderr, err)
 39			os.Exit(1)
 40		}
 41	
 42		root := &cobra.Command{
 43			Use:   "jsverbs-example",
 44			Short: "Expose scanned JavaScript functions as Glazed commands",
 45			Long: fmt.Sprintf(
 46				"Scan %s for .js/.cjs files, infer verbs from top-level functions, and run them through goja + Glazed.",
 47				registry.RootDir,
 48			),
 49			PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
 50				return logging.InitLoggerFromCobra(cmd)
 51			},
 52		}
 53		root.PersistentFlags().StringP("dir", "d", dir, "Directory scanned before command registration")
 54		if err := logging.AddLoggingSectionToRootCommand(root, "jsverbs-example"); err != nil {
 55			fmt.Fprintln(os.Stderr, err)
 56			os.Exit(1)
 57		}
 58		setDefaultFlagValue(root, "log-level", "error")
 59		setDefaultFlagValue(root, "log-format", "text")
 60	
 61		root.AddCommand(&cobra.Command{
 62			Use:   "list",
 63			Short: "List discovered JS verbs",
 64			Run: func(cmd *cobra.Command, args []string) {
 65				paths := make([]string, 0, len(registry.Verbs()))
 66				for _, verb := range registry.Verbs() {
 67					paths = append(paths, fmt.Sprintf("%s\t%s", verb.FullPath(), verb.SourceRef()))
 68				}
 69				sort.Strings(paths)
 70				fmt.Fprintln(cmd.OutOrStdout(), strings.Join(paths, "\n"))
 71			},
 72		})
 73	
 74		if err := cli.AddCommandsToRootCommand(
 75			root,
 76			commands,
 77			nil,
 78			cli.WithParserConfig(cli.CobraParserConfig{
 79				ShortHelpSections: []string{schema.DefaultSlug},
 80				MiddlewaresFunc:   cli.CobraCommandDefaultMiddlewares,
 81			}),
 82		); err != nil {
 83			fmt.Fprintln(os.Stderr, err)
 84			os.Exit(1)
 85		}
 86	
 87		helpSystem := help.NewHelpSystem()
 88		if err := sharedoc.AddDocToHelpSystem(helpSystem); err != nil {
 89			fmt.Fprintf(os.Stderr, "warning: failed to load help docs: %v\n", err)
 90		}
 91		help_cmd.SetupCobraRootCommand(helpSystem, root)
 92	
 93		if err := root.Execute(); err != nil {
 94			os.Exit(1)
 95		}
 96	}
