 98	func discoverDirectory(args []string) string {
 99		for i := 0; i < len(args); i++ {
100			arg := args[i]
101			switch {
102			case arg == "--dir" || arg == "-d":
103				if i+1 < len(args) {
104					return args[i+1]
105				}
106			case strings.HasPrefix(arg, "--dir="):
107				return strings.TrimPrefix(arg, "--dir=")
108			}
109		}
110		return defaultExampleDir
111	}
112	
113	func setDefaultFlagValue(root *cobra.Command, name string, value string) {
114		flag := root.PersistentFlags().Lookup(name)
115		if flag == nil {
116			return
117		}
118		flag.DefValue = value
119		_ = flag.Value.Set(value)
120	}
121	
122	func registerExampleSharedSections(dir string, registry *jsverbs.Registry) error {
123		if registry == nil {
124			return fmt.Errorf("registry is nil")
125		}
126		if filepath.Base(filepath.Clean(dir)) != "registry-shared" {
127			return nil
128		}
129	
130		return registry.AddSharedSection(&jsverbs.SectionSpec{
131			Slug:        "filters",
132			Title:       "Registry Filters",
133			Description: "Example host-registered shared filter flags for jsverbs-example.",
134			Fields: map[string]*jsverbs.FieldSpec{
135				"state": {
136					Type:    "choice",
137					Choices: []string{"open", "closed"},
138					Default: "open",
139					Help:    "Issue state",
140				},
141				"labels": {
142					Type: "stringList",
143					Help: "Labels to filter on",
144				},
145			},
146		})
147	}

